function missionCard(id,title,desc,risk,reward){const done=state.missions.includes(id)||state.gyms.includes(id)||state.towns.includes(id);const locked=(id==='brass'&&!state.missions.includes('dock'))||(id==='tideline'&&!state.gyms.includes('brass'))||(id==='market'&&!state.towns.includes('tideline'));return `<div class="op-card"><div class="op-badge">${id==='dock'?'⌖':id==='brass'?'♜':'⌂'}</div><div style="flex:1"><h3>${title}</h3><p>${desc}</p><div class="op-meta"><span>${risk} RISK</span><span>${reward}</span></div></div><button class="btn ${done?'ghost':'secondary'}" data-mission="${id}" ${locked||done?'disabled':''}>${done?'CLEARED':locked?'LOCKED':'GO'}</button></div>`}
function renderCorner(){const jackpot=250+state.upgrades.slots*100;const luck=state.upgrades.luck;root.innerHTML=pageHead('ENTERTAINMENT / FRONT BUSINESS','The Game Corner','Keep the lights on. One lucky pull could fund your whole operation.','HOUSE EDGE: '+(luck?`${5-luck}%`:'10%'))+`<div class="corner-layout"><div class="machine"><div class="machine-top"><span>▣ ROCKET REELS · 3-REEL SLOT</span><span class="jackpot">JACKPOT ${jackpot}¢</span></div><div class="slot-frame"><div class="reels"><div class="reel" id="reel-0">🍒</div><div class="reel" id="reel-1">◆</div><div class="reel" id="reel-2">7</div></div><div class="slot-controls"><label>BET</label><div class="bet-step"><button id="bet-down">−</button><strong id="bet-value">${state.bet}</strong><button id="bet-up">+</button></div><button class="btn spin-button" id="spin-btn">PULL LEVER ↗</button></div><div class="slot-result" id="slot-result">${state.lastSpin||'GOOD LUCK, GRUNT.'}</div></div><div class="btn-row" style="justify-content:center"><button class="btn secondary" id="shift-btn">WORK A SHIFT &nbsp; +20¢</button><button class="btn ghost" id="corner-upgrades">CORNER UPGRADES</button></div><p style="color:#819692;font-size:9px;text-align:center;margin:13px 0 0">Credits earned here buy permanent upgrades across the campaign.</p></div><div class="panel"><div class="panel-head"><h2>Prize counter</h2><span>AVAILABLE STOCK</span></div>${shopItem('💼','Field kit','+5 max HP for every creature',80,'fieldkit')}${shopItem('📡','Recruitment ledger','Unlock a new crew slot and a free creature',120,'pockets')}${shopItem('🎯','Training regimen','+2 attack for all your creatures',100,'training')}${shopItem('🍀','Lucky jacket','Better reels and better odds',140,'luck')}${shopItem('🔧','Slot tuner','Better slot payouts at the Corner',180,'slots')}<div class="notice" style="margin-top:12px"><b>Credits:</b> ${state.credits}¢ on hand · ${state.upgrades.luck?'Lucky jacket improves odds.':'First prize upgrade unlocks at Runner rank.'}</div></div></div>`;
 $('#bet-down').onclick=()=>{state.bet=Math.max(1,state.bet-5);$('#bet-value').textContent=state.bet};$('#bet-up').onclick=()=>{state.bet=Math.min(50,state.bet+5);$('#bet-value').textContent=state.bet};$('#spin-btn').onclick=spin;$('#shift-btn').onclick=workShift;$('#corner-upgrades').onclick=()=>setView('corner');root.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buyPrize(b.dataset.buy));
}
function shopItem(icon,name,desc,cost,id){let owned=(id==='fieldkit'&&state.upgrades.training>=1)||(id!=='fieldkit'&&state.upgrades[id]>0);return `<div class="shop-item"><div class="shop-glyph">${icon}</div><div><strong>${name}</strong><small>${desc}</small></div><div class="price">${owned?'OWNED':cost+'¢'}${owned?'':`<button class="btn secondary" data-buy="${id}" ${state.credits<cost?'disabled':''}>BUY</button>`}</div></div>`}
function workShift(){state.credits+=20+state.rank*5;state.morale=Math.min(100,state.morale+5);state.day++;state.lastSpin='Shift complete. +'+(20+(state.rank-0)*5)+'¢';save();render();toast('Shift complete. Credits added.')}
function spin(){if(state.credits<state.bet){toast('Not enough credits to bet that much.');return}state.credits-=state.bet;const symbols=['🍒','◆','7','★','●','⚡'];const weights=[28,24,16,12,10+state.upgrades.luck*2,10+state.upgrades.luck*3];const pick=()=>{let n=Math.random()*weights.reduce((a,b)=>a+b,0);for(let i=0;i<weights.length;i++){n-=weights[i];if(n<=0)return symbols[i]}return symbols[0]};let r=[pick(),pick(),pick()];for(let i=0;i<3;i++)$('#reel-'+i).textContent=r[i];let win=0;if(r[0]===r[1]&&r[1]===r[2]){const mult={'🍒':5,'◆':7,'7':10,'★':14,'●':18,'⚡':25};win=state.bet*mult[r[0]]+state.upgrades.slots*10;if(r[0]==='⚡')win+=Math.floor(state.credits*.4)}else if(r.filter(a=>a==='🍒').length>=2)win=state.bet*2;else if(new Set(r).size===2)win=state.bet;
 state.credits+=win;state.lastSpin=win?`WIN! ${r.join(' ')}  +${win}¢`:`${r.join(' ')}  NO PAYOUT`;if(win){state.morale=Math.min(100,state.morale+Math.min(12,Math.ceil(win/20)));toast(`You won ${win} credits!`)}else toast('No payout this time.');save();$('#slot-result').textContent=state.lastSpin;$('#credit-label').textContent=String(state.credits).padStart(3,'0');root.querySelectorAll('[data-buy]').forEach(b=>b.disabled=state.credits<Number(b.textContent.replace('BUY','')))}
function buyPrize(id){const costs={fieldkit:80,pockets:120,training:100,luck:140,slots:180};const cost=costs[id];if(state.credits<cost)return toast('Not enough credits.');if(id==='fieldkit'&&state.upgrades.training>=1)return toast('Already purchased.');if(id!=='fieldkit'&&state.upgrades[id]>0)return toast('Already purchased.');if(id==='pockets'&&state.caught.length>=6)return toast('Your crew is full.');state.credits-=cost;if(id==='fieldkit'){state.upgrades.training=1;state.caught.forEach(c=>{c.maxHp+=5;c.hp+=5})}else if(id==='pockets'){state.upgrades.pockets=1;const c=CREATURES.find(x=>!state.caught.some(y=>y.id===x.id));if(c){state.caught.push(freshCreature(c.id));state.team.push(c.id)}}else if(id==='training'){state.upgrades.training=2;state.caught.forEach(c=>c.atk+=2)}else state.upgrades[id]=1;state.lastSpin=`${id.toUpperCase()} acquired.`;save();render();toast('Permanent upgrade acquired!')}

