function rankUp(to){if(to>state.rank){state.rank=to;state.morale=Math.min(100,state.morale+20);state.player.maxHp+=5;state.player.hp=state.player.maxHp;state.caught.forEach(c=>{c.atk+=1;c.maxHp+=3;c.hp=c.maxHp});toast(`PROMOTION! ${['ROOKIE','RUNNER','CAPTAIN','BOSS'][to]} RANK.`)}}
function renderLeague(){
  const names=['The Verdant Ace','The Iron Warden','The Tempest Star','Nia Vale · Champion'];
  const locked=state.rank<3||state.towns.length<3;
  const completed=state.league>=5;
  const steps=names.map((name,i)=>`<div class="league-step"><span>MATCH ${String(i+1).padStart(2,'0')}</span><strong>${name}</strong><small>${state.league>i||completed?'DEFEATED':state.league===i?'READY':'AWAITING'}</small></div>`).join('');
  root.innerHTML=pageHead('THE GRAND CIRCUIT / ENDGAME','League Takeover','The syndicate has taken the city. Now take the title—and settle things with Nia.','CONTROL: '+(completed?'100%':Math.min(100,state.league*25)+'%'))+
    `<div class="league-banner"><div><div class="eyebrow">CHAMPION’S SUMMIT</div><h2>${completed?'THE LEAGUE ANSWERS TO YOU':'Four matches. One throne.'}</h2><p>${locked?'Boss clearance and three controlled towns are required before the League will admit your crew.':completed?'The old champion is gone. Your organization now runs the city and the circuit.':'Nia Vale is waiting at the top. Win four consecutive title matches to seize control.'}</p><button class="btn" id="league-challenge" ${locked||completed?'disabled':''}>${locked?'ACCESS LOCKED':completed?'TITLE SECURED':'CHALLENGE MATCH '+(state.league+1)+' →'}</button></div><div class="banner-status">${completed?'CHAMPION':'CONTROL '+Math.min(100,state.league*25)+'%'}</div></div><div class="league-steps">${steps}</div>`+
    (state.rank>=3?`<section class="org-panel"><div class="panel-head"><h2>Organization management</h2><span>HQ / BOSS OFFICE</span></div><p class="org-copy">A Boss needs more than a strong crew. Invest syndicate funds in the people and infrastructure that keep the operation running.</p><div class="org-grid"><div class="shop-item"><div class="shop-glyph">♟</div><div><strong>Hire a floor manager</strong><small>Raises morale and daily shift pay. ${state.upgrades.staff?'Already hired.':'One-time appointment.'}</small></div><div class="price">${state.upgrades.staff?'HIRED':'90¢'}<button class="btn secondary" data-org="staff" ${state.upgrades.staff||state.credits<90?'disabled':''}>HIRE</button></div></div><div class="shop-item"><div class="shop-glyph">▦</div><div><strong>Expand the hideout</strong><small>Each expansion adds 5 max HP to your operative and crew.</small></div><div class="price">${100+state.baseLevel*100}¢<button class="btn secondary" data-org="base">EXPAND</button></div></div><div class="shop-item"><div class="shop-glyph">◉</div><div><strong>Open a neighborhood front</strong><small>Secure local income. ${state.upgrades.staff?'Manager bonus active.':'Hire a manager first for the daily bonus.'}</small></div><div class="price">${state.upgrades.slots?'OPEN':'150¢'}<button class="btn secondary" data-org="front" ${state.upgrades.slots||state.credits<150?'disabled':''}>${state.upgrades.slots?'OPEN':'OPEN FRONT'}</button></div></div></div><div class="notice" style="margin-top:12px"><b>Daily operation:</b> ${state.upgrades.staff?'Your manager adds 15¢ and 3 morale whenever you work a shift.':'Work a shift from the Game Corner to earn operating funds.'} Current hideout level: ${state.baseLevel}.</div></section>`:'');
