36:function renderIntro(){root.innerHTML=`<div class="intro"><div class="intro-card"><div class="eyebrow">A POCKET-SIZED CRIME RPG · 199X</div><h1>THE CITY IS<br><em>UP FOR GRABS.</em></h1><p>You're the newest grunt in a crumbling syndicate. Build a crew, win street fights, and turn a forgotten hideout into the city's nerve center. The old-school rules still apply—just not to you.</p><div class="intro-items"><span>▣ CREW BATTLES</span><span>◉ UNDERGROUND CASINO</span><span>⚗ CREATURE FUSION</span><span>♜ LEAGUE TAKEOVER</span></div><button class="btn" id="start-btn">CLOCK IN, ROOKIE &nbsp; →</button><p style="font-size:9px;margin-top:18px">Original creatures and characters · Game saves in this browser</p></div></div>`;$('#start-btn').onclick=()=>openStarter()}
37:function openStarter(){modal(`<div class="eyebrow">YOUR FIRST ASSIGNMENT</div><p style="font-size:12px;color:#aab9b1;line-height:1.55">Boss Vanta needs a creature handler. Pick a partner from the abandoned daycare intake. A good grunt never goes topside alone.</p><div class="lab-grid">${CREATURES.slice(0,3).map(c=>`<div class="creature-card"><div class="creature-art">${c.icon}</div><div><h3>${c.name}</h3><p>${c.type} · HP ${c.hp} · ATK ${c.atk}</p><button class="btn secondary" data-starter="${c.id}">RECRUIT</button></div></div>`).join('')}</div>`,'Choose your partner');document.querySelectorAll('[data-starter]').forEach(b=>b.onclick=()=>{state.team=[b.dataset.starter];state.caught=[freshCreature(b.dataset.starter)];state.started=true;state.day=1;state.missions=[];state.view='base';state.morale=64;modalClose();save();render();toast(`${creature(b.dataset.starter).name} joined your crew.`)})}
