+function missionCard(id,title,desc,risk,reward){const done=state.missions.includes(id)||state.gyms.includes(id)||state.towns.includes(id);const locked=(id==='brass'&&!state.missions.includes('dock'))||(id==='tideline'&&!state.gyms.includes('brass'))||(id==='market'&&!state.towns.includes('tideline'))||(id==='skyline'&&!state.towns.includes('tideline'))||(id==='hilltown'&&!state.gyms.includes('skyline'));return `<div class="op-card"><div class="op-badge">${id==='dock'?'⌖':id==='brass'||id==='skyline'?'♜':'⌂'}</div><div style="flex:1"><h3>${title}</h3><p>${desc}</p><div class="op-meta"><span>${risk} RISK</span><span>${reward}</span></div></div><button class="btn ${done?'ghost':'secondary'}" data-mission="${id}" ${locked||done?'disabled':''}>${done?'CLEARED':locked?'LOCKED':'GO'}</button></div>`}
 function renderCorner(){const jackpot=250+state.upgrades.slots*100;const luck=state.upgrades.luck;root.innerHTML=pageHead('ENTERTAINMENT / FRONT BUSINESS','The Game Corner','Keep the lights on. One lucky pull could fund your whole operation.','HOUSE EDGE: '+(luck?`${5-luck}%`:'10%'))+`<div class="corner-layout"><div class="machine"><div class="machine-top"><span>▣ ROCKET REELS · 3-REEL SLOT</span><span class="jackpot">JACKPOT ${jackpot}¢</span></div><div class="slot-frame"><div class="reels"><div class="reel" id="reel-0">🍒</div><div class="reel" id="reel-1">◆</div><div class="reel" id="reel-2">7</div></div><div class="slot-controls"><label>BET</label><div class="bet-step"><button id="bet-down">−</button><strong id="bet-value">${state.bet}</strong><button id="bet-up">+</button></div><button class="btn spin-button" id="spin-btn">PULL LEVER ↗</button></div><div class="slot-result" id="slot-result">${state.lastSpin||'GOOD LUCK, GRUNT.'}</div></div><div class="btn-row" style="justify-content:center"><button class="btn secondary" id="shift-btn">WORK A SHIFT &nbsp; +20¢</button><button class="btn ghost" id="corner-upgrades">CORNER UPGRADES</button></div><p style="color:#819692;font-size:9px;text-align:center;margin:13px 0 0">Credits earned here buy permanent upgrades across the campaign.</p></div><div class="panel"><div class="panel-head"><h2>Prize counter</h2><span>AVAILABLE STOCK</span></div>${shopItem('💼','Field kit','+5 max HP for every creature',80,'fieldkit')}${shopItem('📡','Recruitment ledger','Unlock a new crew slot and a free creature',120,'pockets')}${shopItem('🎯','Training regimen','+2 attack for all your creatures',100,'training')}${shopItem('🍀','Lucky jacket','Better reels and better odds',140,'luck')}${shopItem('🔧','Slot tuner','Better slot payouts at the Corner',180,'slots')}<div class="notice" style="margin-top:12px"><b>Credits:</b> ${state.credits}¢ on hand · ${state.upgrades.luck?'Lucky jacket improves odds.':'First prize upgrade unlocks at Runner rank.'}</div></div></div>`;
  $('#bet-down').onclick=()=>{state.bet=Math.max(1,state.bet-5);$('#bet-value').textContent=state.bet};$('#bet-up').onclick=()=>{state.bet=Math.min(50,state.bet+5);$('#bet-value').textContent=state.bet};$('#spin-btn').onclick=spin;$('#shift-btn').onclick=workShift;$('#corner-upgrades').onclick=()=>setView('corner');root.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buyPrize(b.dataset.buy));
 }
 function shopItem(icon,name,desc,cost,id){let owned=state.upgrades[id]>0;return `<div class="shop-item"><div class="shop-glyph">${icon}</div><div><strong>${name}</strong><small>${desc}</small></div><div class="price">${owned?'OWNED':cost+'¢'}${owned?'':`<button class="btn secondary" data-buy="${id}" ${state.credits<cost?'disabled':''}>BUY</button>`}</div></div>`}

