 function startMission(id){const data={dock:{title:'Dockside shake-down',enemy:{name:'League Courier',icon:'🧑‍✈️',hp:26,atk:6,def:2}},brass:{title:'Brass Gym takeover',enemy:{name:'Foreman Ivo',icon:'🧔',hp:36,atk:8,def:3}},tideline:{title:'Tidelinе town push',enemy:{name:'Harbor Captain',icon:'🧑‍✈️',hp:38,atk:8,def:4}},market:{title:'Market Row takeover',enemy:{name:'Night Market Boss',icon:'🕶️',hp:44,atk:9,def:4}},skyline:{title:'Skyline Gym takeover',enemy:{name:'Gym Leader Volt',icon:'🧑‍🎤',hp:50,atk:10,def:4}},hilltown:{title:'Hilltown control',enemy:{name:'Farmstead Marshal',icon:'👨‍🌾',hp:54,atk:10,def:5}}}[id];if(!data)return;const tier=state.rank;data.kind='mission';data.id=id;data.reward=35+state.rank*25;data.enemy.hp+=tier*5;startBattle(data)}
