 function showBattle(b){const c=creature(b.active);modal(`<div class="battle-scene"><div class="battle-stats"><div class="statline"><span>${c.name} · LV ${c.level||1}</span><b>${c.hp}/${c.maxHp}</b></div><div class="progress-track"><i style="width:${100*c.hp/c.maxHp}%;background:${c.hp/c.maxHp<.3?'var(--red)':'var(--lime)'}"></i></div><div class="battle-mon">${c.icon}</div></div><div style="font:9px var(--pixel);color:#829792">VS</div><div class="battle-stats"><div class="statline"><span>${b.enemy.name}</span><b>${Math.max(0,b.enemy.hp)}/${b.enemy.maxHp}</b></div><div class="progress-track"><i style="width:${Math.max(0,100*b.enemy.hp/b.enemy.maxHp)}%;background:var(--orange)"></i></div><div class="battle-mon">${b.enemy.icon}</div></div></div><div class="battle-log" id="battle-log">${b.log}</div><div class="battle-actions">${b.done?'<button class="btn" id="battle-close">CONTINUE →</button>':`<button class="btn" id="attack-btn">STRIKE · ${c.atk+(state.upgrades.training?2:0)} ATK</button><button class="btn secondary" id="special-btn">TEAM TACTIC</button>${state.team.some(id=>id!==b.active&&creature(id).hp>0)?'<button class="btn secondary" id="switch-btn">SWITCH CREATURE</button>':''}${b.kind==='mission'&&b.id==='dock'&&!state.caught.some(a=>a.id==='craglet')?'<button class="btn ghost" id="capture-btn">THROW CAPSULE</button>':''}<button class="btn ghost" id="retreat-btn">RETREAT</button>`}</div>${b.done?`<div class="battle-result">${b.result}</div>`:''}` ,b.title);if(b.done){$('#battle-close').onclick=()=>{modalClose();render()};return}$('#attack-btn').onclick=()=>battleTurn(b,'attack');$('#special-btn').onclick=()=>battleTurn(b,'special');$('#switch-btn')?.addEventListener('click',()=>openBattleSwitch(b));$('#capture-btn')?.addEventListener('click',()=>battleTurn(b,'capture'));$('#retreat-btn').onclick=()=>{if(confirm('Retreat from this fight?')){modalClose();toast('You withdrew from the fight.')}}}
 function openBattleSwitch(b){const options=state.team.filter(id=>id!==b.active&&creature(id).hp>0);if(!options.length)return toast('No other crew members can fight.');modal(`<p style="font-size:11px;color:#9eafaa">Choose a creature to send in. Switching uses your turn.</p><div class="lab-grid">${options.map(id=>{const c=creature(id);return `<button class="creature-card" data-battle-switch="${id}" style="text-align:left;color:inherit;cursor:pointer"><span class="creature-art">${c.icon}</span><span><b>${c.name}</b><br><small style="color:#91a5a4">${c.type} · HP ${c.hp}/${c.maxHp} · ATK ${c.atk}</small></span></button>`}).join('')}</div><button class="btn ghost" id="switch-cancel">BACK TO BATTLE</button>`,'Choose your fighter');document.querySelectorAll('[data-battle-switch]').forEach(button=>button.onclick=()=>battleTurn(b,'switch',button.dataset.battleSwitch));$('#switch-cancel').onclick=()=>showBattle(b)}
- function battleTurn(b,action,targetId){if(b.done)return;let c=creature(b.active);let message='';if(action==='capture'){if(b.enemy.hp>b.enemy.maxHp*.45){message='The target is still too strong to catch!';}else if(state.caught.length>=6){message='Your crew is full!';}else if(Math.random()<.78){const newcomer=freshCreature('craglet');state.caught.push(newcomer);state.team.push(newcomer.id);message=`Caught Craglet! ${newcomer.name} joined the crew. Keep fighting!`;}else message='The capsule shook free!';}else if(action==='switch'){const next=creature(targetId);if(!next||next.hp<=0||!state.team.includes(targetId))return showBattle(b);message=`${c.name}, come back! Go, ${next.name}!`;b.active=targetId;c=next;}else{const damage=action==='special'?Math.max(5,c.atk+state.player.atk+Math.floor(Math.random()*5)-b.enemy.def):Math.max(2,c.atk+(state.upgrades.training?2:0)+Math.floor(Math.random()*4)-b.enemy.def);b.enemy.hp-=damage;message=`${action==='special'?'Team tactic':'Strike'} deals ${damage} damage!`;if(b.enemy.hp<=0){b.enemy.hp=0;if(b.enemyIndex+1<b.enemyParty.length){const defeated=b.enemy.name;b.enemyIndex++;const next=b.enemyParty[b.enemyIndex];b.enemy={...next,hp:next.hp,maxHp:next.hp,index:b.enemyIndex};message+=` ${defeated} is defeated! ${b.enemy.name} enters the battle.`;}else{b.done=true;message+=' Opposing team defeated.';finishBattle(b,c)}}}
+ function battleTurn(b,action,targetId){if(b.done)return;let c=creature(b.active);let message='';if(action==='capture'){if(b.enemy.hp>b.enemy.maxHp*.45){message='The target is still too strong to catch!';}else if(state.caught.length>=6){message='Your crew is full!';}else if(Math.random()<.78){const newcomer=freshCreature('craglet');state.caught.push(newcomer);state.team.push(newcomer.id);message=`Caught Craglet! ${newcomer.name} joined the crew. Keep fighting!`;}else message='The capsule shook free!';}else if(action==='switch'){const next=creature(targetId);if(!next||next.hp<=0||!state.team.includes(targetId))return showBattle(b);message=`${c.name}, come back! Go, ${next.name}!`;b.active=targetId;c=next;}else{const baseDamage=action==='special'?Math.max(5,c.atk+state.player.atk+Math.floor(Math.random()*5)-b.enemy.def):Math.max(2,c.atk+(state.upgrades.training?2:0)+Math.floor(Math.random()*4)-b.enemy.def);const hit=damageWithTypes(baseDamage,c,b.enemy),damage=hit.damage;b.enemy.hp-=damage;const effectiveness=hit.effectiveness===0?' It has no effect!':hit.effectiveness>1?' It is super effective!':hit.effectiveness<1?' It is not very effective.':'';message=`${action==='special'?'Team tactic':'Strike'} deals ${damage} damage!${effectiveness}`;if(b.enemy.hp<=0){b.enemy.hp=0;if(b.enemyIndex+1<b.enemyParty.length){const defeated=b.enemy.name;b.enemyIndex++;const next=b.enemyParty[b.enemyIndex];b.enemy={...next,hp:next.hp,maxHp:next.hp,index:b.enemyIndex};message+=` ${defeated} is defeated! ${b.enemy.name} enters the battle.`;}else{b.done=true;message+=' Opposing team defeated.';finishBattle(b,c)}}}
  if(!b.done){const hurt=Math.max(2,b.enemy.atk-(c.def||2)-Math.floor(Math.random()*2));c.hp=Math.max(0,c.hp-hurt);message+=` ${b.enemy.name} hits ${c.name} for ${hurt}.`;if(c.hp<=0){const nextId=state.team.find(id=>id!==c.id&&creature(id).hp>0);if(nextId){b.active=nextId;message+=` ${c.name} is down! ${creature(nextId).name}, take over!`;}else{b.done=true;b.result='YOUR CREW IS DOWN — RECOVER AT THE DAYCARE';message+=` ${c.name} can no longer fight.`}}}
  b.log=message;save();showBattle(b)}
 function finishBattle(b,c){c.xp=(c.xp||0)+20;if(c.xp>=40){c.level=(c.level||1)+1;c.xp=0;c.maxHp+=3;c.hp=Math.min(c.maxHp,c.hp+8);c.atk+=1}state.credits+=b.reward||0;state.morale=Math.min(100,state.morale+8);state.day++;
