import { createRequire } from 'node:module'
import { mkdirSync } from 'node:fs'
const runtime='/home/runner/.local/share/omgithub-playwright'
const require=createRequire(runtime+'/package.json')
const { chromium }=require('playwright')
const browser=await chromium.launch({headless:true})
const errors=[]
try {
 const page=await browser.newPage({viewport:{width:1280,height:960},deviceScaleFactor:1})
 page.on('pageerror',e=>errors.push(e.message))
 let response=await page.goto('http://localhost:3000/',{waitUntil:'networkidle'})
 if(!response?.ok()) throw Error('app failed to load')
 await page.locator('#start-btn').click()
 await page.locator('[data-starter]').first().click()
 await page.locator('.scene-card').waitFor()
 mkdirSync('screenshots',{recursive:true})
 await page.screenshot({path:'screenshots/neon-syndicate.jpg',type:'jpeg',quality:90,fullPage:true})
 const size=await page.evaluate(()=>({w:innerWidth,h:innerHeight}))
 if(size.w>1280) throw Error(`capture viewport too wide: ${size.w}`)
 await page.locator('[data-view="field"]').click()
 await page.locator('[data-travel="Cerulean City"]').click()
 await page.locator('#steal-bike').click()
 if(!(await page.locator('.town-detail').innerText()).includes('stolen bike')) throw Error('bike story event did not render')
 await page.locator('#map-trainer').click()
 await page.locator('.battle-scene').waitFor()
 await page.locator('#retreat-btn').click()
 page.once('dialog',d=>d.accept())
 await page.waitForTimeout(100)
 await page.locator('[data-travel="Safari Zone"]').click()
 await page.evaluate(()=>{state.credits=250;save();render()})
 await page.locator('#safari-explore').click()
 const safari=await page.evaluate(()=>({caught:state.caught.length,team:state.team.length,mon:state.caught.at(-1)}))
 if(safari.caught<2||safari.team<2||safari.mon.hp<=0||safari.mon.maxHp<=0) throw Error('Safari capture was not battle-ready')
 await page.locator('#safari-control').click()
 await page.locator('[data-view="corner"]').click()
 const before=await page.evaluate(()=>state.credits)
 await page.locator('#shift-btn').click()
 const after=await page.evaluate(()=>state.credits)
 if(after-before!==45) throw Error(`Safari shift income expected 45, got ${after-before}`)
 await page.locator('[data-view="league"]').click()
 if(!(await page.locator('#league-challenge').isDisabled())) throw Error('League gate unexpectedly open')
 await page.evaluate(()=>{state.rank=3;state.towns=['tideline','market','hilltown'];state.league=0;state.leagueBadges=[];render()})
 if(await page.locator('#league-challenge').isDisabled()) throw Error('Boss-rank League access did not unlock')
 const partySizes=await page.evaluate(()=>Array.from({length:4},(_,i)=>leagueParty(leagueStage(11+i)).length))
 if(partySizes.some(n=>n!==6)) throw Error(`Elite Four party sizes incorrect: ${partySizes}`)
 await page.locator('#league-challenge').click()
 await page.locator('.battle-scene').waitFor()
 await page.locator('#retreat-btn').click()
 page.once('dialog',d=>d.accept())
 await page.waitForTimeout(100)
 await page.close()
 const migration=await browser.newPage({viewport:{width:1024,height:768}})
 await migration.goto('http://localhost:3000/')
 await migration.evaluate(()=>localStorage.setItem('neon-syndicate-save',JSON.stringify({started:true,league:4,leagueVersion:1,rank:3,towns:['a','b','c']})))
 await migration.reload()
 const migrated=await migration.evaluate(()=>({league:state.league,version:state.leagueVersion}))
 if(migrated.league!==16||migrated.version!==2) throw Error(`save migration failed: ${JSON.stringify(migrated)}`)
 if(errors.length) throw Error(`browser errors: ${errors.join('; ')}`)
 console.log(JSON.stringify({ok:true,viewport:size,safariCapture:{species:safari.mon.name,hp:safari.mon.hp,maxHp:safari.mon.maxHp},safariShiftIncome:after-before,elitePartySizes:partySizes,migrated,jpeg:'screenshots/neon-syndicate.jpg'},null,2))
} finally { await browser.close() }

